import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Card,
  Container,
  Row,
  Col,
  Form,
  Button,
} from "react-bootstrap";
import "chartist/dist/chartist.min.css";

//============= STYLE ===============
const themeStyle = `
  .chart-scroll {
    overflow-x: auto;
    overflow-y: hidden;
  }

  /* ปรับส่วนหัวให้เป็นสีม่วงไล่เฉดตามรูป (Purple Gradient) */
  .history-header {
    background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
    border-radius: 8px 8px 0 0 !important;
    padding: 20px !important;
  }

  .history-header .card-title {
    color: white !important;
    margin: 0 !important;
    font-weight: bold;
    font-size: 1.25rem;
  }

  /* ตกแต่งช่องเลือก (Select) ให้ดูสะอาดตาและโค้งมน */
  .form-select {
    border-radius: 12px !important; 
    padding: 10px 18px !important;
    border: 1px solid #e9ecef !important;
    background-color: #ffffff !important;
    box-shadow: 0 1px 3px rgba(0, 0, 0, .08) !important;
    font-size: 14px !important;
    color: #525f7f !important;
  }

  /* ปรับสี Label ให้เป็นสีม่วงเข้ม/น้ำเงิน ตามสไตล์ในรูป */
  .form-label {
    font-weight: 700;
    color: #5e72e4;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: .025em;
    margin-bottom: 8px;
  }

  /* ตกแต่ง Card ให้มีเงาฟุ้งๆ (Soft Shadow) เหมือนในรูป */
  .card {
    border: none !important;
    box-shadow: 0 0 2rem 0 rgba(136, 152, 170, .15) !important;
    margin-bottom: 30px !important;
    border-radius: 0.75rem !important;
    background-color: #ffffff !important;
  }

  /* สไตล์เพิ่มเติมสำหรับปุ่มหรือ Badge ที่เป็นสีม่วง (ถ้ามี) */
  .btn-primary, .badge-primary {
    background-color: #5e72e4 !important;
    border-color: #5e72e4 !important;
    border-radius: 10px !important;
  }

  .bg-transparent {
    background-color: transparent !important;
  }
`;

const SLOT_INTERVAL = 10;
const generateTimeSlots = (startHour = 7, endHour = 22, interval = SLOT_INTERVAL) => {
  const slots = [];
  const startMin = startHour * 60;
  const endMin = endHour * 60;
  for (let m = startMin; m <= endMin; m += interval) {
    const h = Math.floor(m / 60);
    const min = m % 60;
    slots.push(`${h.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`);
  }
  return slots;
};

const timeToMinutes = (time) => {
  const [h, m] = time.split(":").map(Number);
  return h * 60 + m;
};

const average30Min = (labels, series) => {
  const bucket = {};

  labels.forEach((label, idx) => {
    const [h, m] = label.split(":").map(Number);

    // ปัดเวลาเข้า 30 นาที
    const roundedMin = m < 30 ? 0 : 30;
    const key = `${h.toString().padStart(2, "0")}:${roundedMin
      .toString()
      .padStart(2, "0")}`;

    if (!bucket[key]) {
      bucket[key] = { sum: 0, count: 0 };
    }

    bucket[key].sum += series[idx];
    bucket[key].count += 1;
  });

  const newLabels = [];
  const newSeries = [];

  Object.keys(bucket).forEach((key) => {
    newLabels.push(key);
    newSeries.push(
      Math.round(bucket[key].sum / bucket[key].count)
    );
  });

  return { labels: newLabels, series: newSeries };
};

const CAMERA_MAP = {
