};


// รวมข้อมูลที่เวลาซ้ำ (HH:mm เดิม) ให้เหลือแท่งเดียว
// ใช้ "ค่าสูงสุด" ของนาทีนั้น
const mergeSameMinute = (labels, values) => {
  const map = {};
  const order = [];

  labels.forEach((label, i) => {
    const value = values[i];

    if (!map[label]) {
      map[label] = value;
      order.push(label); // เก็บลำดับเดิมไว้
    } else {
      map[label] = Math.max(map[label], value);
    }
  });

  return {
    labels: order,
    series: [order.map(l => map[l])],
  };
};

